    let old_scale = self.scale();

    // return early if decimal has a smaller number of fractional places than dp
    // e.g. 2.51 rounded to 3 decimal places is 2.51
    if old_scale <= dp {
        return *self;
    }

    // Short circuit for zero
    if self.is_zero() {
        return Decimal {
            lo: 0,
            mid: 0,
            hi: 0,
            flags: flags(self.is_sign_negative(), dp),
        };
    }

